DROP TABLE IF EXISTS `submission_status`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `submission_status` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `score` decimal(5,2) DEFAULT NULL,
  `status` enum('NOT_SUBMITTED','SUBMITTED','LATE_SUBMITTED','EXCUSED') DEFAULT NULL,
  `submitted_at` datetime(6) DEFAULT NULL,
  `teacher_note` text,
  `updated_at` datetime(6) DEFAULT NULL,
  `assignment_id` bigint(20) NOT NULL,
  `student_id` bigint(20) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `UKavi99n5a29mo3i8l0544i4crm` (`assignment_id`,`student_id`),
  KEY `FK5wsu9amj7sbfkqv1qpw4w3mnk` (`student_id`),
  CONSTRAINT `FK5wsu9amj7sbfkqv1qpw4w3mnk` FOREIGN KEY (`student_id`) REFERENCES `students` (`id`),
  CONSTRAINT `FKl2t9pnwd0vary602m28xd3bs` FOREIGN KEY (`assignment_id`) REFERENCES `assignments` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=81 DEFAULT CHARSET=utf8;
